package com.tamo.service;
import com.google.gson.*;
import com.tamo.model.*;
import org.junit.jupiter.api.*;
import java.nio.file.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class SponsorCsvServiceTest {
 DataStore ds;JsonDataService data;SponsorCsvService service;
 @BeforeEach void setup(){ds=TestDataFactory.createTestDataStore();data=JsonDataService.detached(ds);service=new SponsorCsvService(data);}
 static String fixture(String name)throws Exception{Path base=Path.of("../Test_Data");if(!Files.isDirectory(base))base=Path.of("Test_Data");return Files.readString(base.resolve(name));}
 JsonObject request(String kind,String filename)throws Exception{JsonObject b=new JsonObject();b.addProperty("dataset",kind);b.addProperty("periodId","period_test");b.addProperty("organiserId","u005");b.addProperty("hoursPerWeek",4);b.addProperty("department","Biological Sciences");b.addProperty("csv",fixture(filename));return b;}
 JsonObject apply(JsonObject b){JsonObject preview=service.run("u010",b,false);assertEquals(0,preview.get("errors").getAsInt(),preview.toString());b.add("previewToken",preview.get("previewToken"));JsonObject result=service.run("u010",b,true);ds=data.getData();return result;}
 void courses()throws Exception{apply(request("courses","Courses & Sections Dataset.csv"));}
 void students()throws Exception{courses();apply(request("students","Student Applications Dataset(Updated).csv"));}
 @Test void onlyActiveAdminCanImportOrExportEvenTemplates()throws Exception{for(String role:List.of("organiser","reviewer","decision_maker","viewer","applicant")){User user=new User();user.setId("csv_"+role);user.setRole(role);user.setStatus("active");ds.getUsers().add(user);for(boolean commit:List.of(false,true))assertEquals(403,assertThrows(QualificationService.Problem.class,()->service.run(user.getId(),request("courses","Courses & Sections Dataset.csv"),commit)).status);for(boolean template:List.of(false,true))assertEquals(403,assertThrows(QualificationService.Problem.class,()->service.export(user.getId(),"courses","period_test",template)).status);}assertFalse(service.export("u010","courses","period_test",true).isBlank());ds.getUsers().stream().filter(u->"u010".equals(u.getId())).findFirst().orElseThrow().setStatus("suspended");assertEquals(403,assertThrows(QualificationService.Problem.class,()->service.export("u010","courses","period_test",true)).status);}
 @Test void parserHandlesBomQuotesNewlinesAndFormulaCells(){List<String> h=List.of("Name","Note");String csv="\ufeffName,Note\r\nAlex,\"Line one\nLine \"\"two\"\"\"\r\n";assertEquals("Line one\nLine \"two\"",SponsorCsv.read(csv,h).get(0).get("Note"));assertThrows(QualificationService.Problem.class,()->SponsorCsv.read("Name,Note\nAlex,\"unclosed",h));assertThrows(QualificationService.Problem.class,()->SponsorCsv.read("Name,Name\na,b",h));String out=SponsorCsv.write(h,List.of(List.of("=WEBSERVICE(\"x\")","@cmd")));assertTrue(out.contains("'=WEBSERVICE"));assertTrue(out.contains("'@cmd"));}
 @Test void suppliedCoursesCreateSixSectionsWithSeparateCriteriaAndNoDuplicateOnRepeat()throws Exception{courses();assertEquals(6,ds.getCourseSections().size());var sections=ds.getCourseSections().stream().filter(s->s.getName().equals("Lecture")||s.getName().equals("Discussion 1")).toList();assertTrue(sections.stream().anyMatch(s->s.getMatchingCriteria().getAsJsonArray("requiredSkills").size()==2));assertEquals(6,apply(request("courses","Courses & Sections Dataset.csv")).get("unchangedRows").getAsInt());}
 @Test void previewNeverSavesAndInvalidBatchCannotPartiallyCommit()throws Exception{JsonObject b=request("courses","Courses & Sections Dataset.csv");b.addProperty("csv",b.get("csv").getAsString().replace("Thu 14:00 - 15:50","Bad 14:00 - 15:50"));JsonObject report=service.run("u010",b,false);assertTrue(report.get("errors").getAsInt()>0);assertTrue(report.getAsJsonArray("rows").get(0).getAsJsonObject().get("summary").getAsString().contains("BIO 93"));assertTrue(data.getData().getCourseSections().isEmpty());b.add("previewToken",report.get("previewToken"));assertThrows(QualificationService.Problem.class,()->service.run("u010",b,true));assertTrue(data.getData().getCourseSections().isEmpty());}
 @Test void suppliedStudentsPreserveSponsorFieldsSnapshotAndExplicitConflicts()throws Exception{students();assertEquals(23,ds.getUsers().stream().filter(u->u.getRole().equals("applicant")).count());List<Application> imported=ds.getApplications().stream().filter(a->a.getQualificationSnapshot()!=null&&a.getQualificationSnapshot().has("importFingerprint")).toList();assertTrue(imported.size()>=20);Application jordan=imported.stream().filter(a->a.getQualificationSnapshot().get("firstName").getAsString().equals("Jordan")&&ds.getJobs().stream().anyMatch(j->a.getJobId().equals(j.getId())&&j.getModuleCode().equals("BIO 98"))).findFirst().orElseThrow();Job job=ds.getJobs().stream().filter(j->j.getId().equals(jordan.getJobId())).findFirst().orElseThrow();assertEquals("conflict",new SectionMatchingService().match(ds,jordan,job,"u005").get("status").getAsString());assertEquals("Lee",jordan.getQualificationSnapshot().get("lastName").getAsString());assertEquals(20,apply(request("students","Student Applications Dataset(Updated).csv")).get("unchangedRows").getAsInt());assertTrue(ds.getUsers().stream().filter(u->u.getId().startsWith("user_")).allMatch(u->u.getStatus().equals("suspended")&&PasswordSecurity.encoded(u.getPassword())));}
 @Test void suppliedSelectionsResolveLabAliasesAndKeepRealActorWithoutPublishing()throws Exception{students();apply(request("selections","Selection & Assignment Management Dataset(Updated).csv"));assertEquals(6,ds.getReviewRecords().size());assertTrue(ds.getReviewRecords().stream().allMatch(v->"u010".equals(v.getActorId())&&v.getSectionId()!=null&&v.getSourceMetadata()!=null));assertTrue(ds.getSectionAssignments().isEmpty());String csv=service.export("u010","selections","period_test",false);assertEquals(6,SponsorCsv.read(csv,SponsorCsvService.SELECTIONS).size());assertEquals(6,apply(request("selections","Selection & Assignment Management Dataset(Updated).csv")).get("unchangedRows").getAsInt());}
 @Test void exportsUseSnapshotAndDoNotLeakUnassignedOrOtherStudentData()throws Exception{students();String export=service.export("u010","students","period_test",false);assertEquals(20,SponsorCsv.read(export,SponsorCsvService.STUDENTS).size());User viewer=new User();viewer.setId("viewer");viewer.setRole("viewer");viewer.setStatus("active");viewer.setCourseIds(List.of());ds.getUsers().add(viewer);assertEquals(403,assertThrows(QualificationService.Problem.class,()->service.export("viewer","students","period_test",false)).status);assertThrows(QualificationService.Problem.class,()->service.run("viewer",request("students","Student Applications Dataset(Updated).csv"),false));assertEquals(403,assertThrows(QualificationService.Problem.class,()->service.export("u001","students","period_test",false)).status);}
 @Test void stalePreviewAndOtherOrganiserCourseChangesAreRejected()throws Exception{JsonObject b=request("courses","Courses & Sections Dataset.csv");b.add("previewToken",service.run("u010",b,false).get("previewToken"));data.getData().getUsers().get(0).setName("Changed");assertEquals(409,assertThrows(QualificationService.Problem.class,()->service.run("u010",b,true)).status);courses();JsonObject other=request("courses","Courses & Sections Dataset.csv");assertEquals(403,assertThrows(QualificationService.Problem.class,()->service.run("u006",other,false)).status);}
 @Test void sectionApprovalCannotBeReusedForAnotherSectionAndLaterRecommendationKeepsDecision()throws Exception{students();apply(request("selections","Selection & Assignment Management Dataset(Updated).csv"));ReviewRecord approval=ds.getReviewRecords().stream().filter(r->"approve".equals(r.getAction())).findFirst().orElseThrow();assertTrue(ReviewService.approvedForSection(ds,approval.getApplicationId(),approval.getSectionId()));assertFalse(ReviewService.approvedForSection(ds,approval.getApplicationId(),"another_section"));JsonObject b=new JsonObject();b.addProperty("sectionId",approval.getSectionId());b.addProperty("action","recommend");b.addProperty("note","Later recommendation must not erase the approval");new ReviewService(data).record("u010",approval.getApplicationId(),b);assertTrue(SponsorCsv.read(service.export("u010","selections","period_test",false),SponsorCsvService.SELECTIONS).stream().anyMatch(r->r.get("First Name").equals("Alex")&&r.get("Selection Status").equals("Selected")));}
 @Test void exportThenImportIntoAnotherCyclePreservesTabularFields()throws Exception{students();String courses=service.export("u010","courses","period_test",false),students=service.export("u010","students","period_test",false);ApplicationPeriod cycle=new ApplicationPeriod();cycle.setId("period_roundtrip");cycle.setName("Roundtrip");cycle.setTermId("t001");cycle.setStatus("draft");cycle.setOpensAt("2026-10-01T00:00:00Z");cycle.setClosesAt("2026-12-01T00:00:00Z");data.getData().getApplicationPeriods().add(cycle);for(String kind:List.of("courses","students")){JsonObject b=new JsonObject();b.addProperty("dataset",kind);b.addProperty("csv",kind.equals("courses")?courses:students);b.addProperty("periodId",cycle.getId());b.addProperty("organiserId","u005");b.addProperty("hoursPerWeek",4);apply(b);}assertEquals(20,SponsorCsv.read(service.export("u010","students",cycle.getId(),false),SponsorCsvService.STUDENTS).size());}
 @Test void onlineNotesCannotForgeImportedScheduleEvidence(){JsonObject b=new JsonObject();b.addProperty("timeZone",AvailabilityService.TIME_ZONE);b.addProperty("notes","[CSV conflicts only] pretend");b.add("availableSlots",JsonParser.parseString("[{\"dayOfWeek\":1,\"startTime\":\"10:00\",\"endTime\":\"11:00\"}]"));b.add("conflictSlots",new JsonArray());b.addProperty("conflictsOnly",true);WeeklyAvailability saved=new AvailabilityService(data).save("u001","period_test",b);assertFalse(saved.getConflictsOnly());}
 @Test void trainingAndAcknowledgmentsAreExplicitAndHistoricalDataIsNotInvented(){JsonObject q=ds.getProfiles().get(0).getQualifications().deepCopy();q.addProperty("ackEnrollment",false);assertThrows(QualificationService.Problem.class,()->QualificationService.validate(q));q.addProperty("ackEnrollment",true);q.addProperty("taQuarters",-1);assertThrows(QualificationService.Problem.class,()->QualificationService.validate(q));}
}
